--- /dev/null
+++ b/game/test/pack-change-active-flight-host.test.mjs
@@ -0,0 +1,226 @@
+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { readFile } from 'node:fs/promises';
+import { soloPage, SoloElement, settle, memoryStorage } from './helpers/solo-dom.mjs';
+import { memoryIndexedDB } from './helpers/soundtrack-fixtures.mjs';
+import { emptyPackLibrary, installPack, preparePack, exportPackLibrary } from '../packs.mjs';
+import { authoritativeCheckpoint } from '../replay.mjs';
+import { emptyLibrary, exportLibrary } from '../library.mjs';
+
+const PACKS_KEY = 'revealline.packs.dev.v1',
+  PROFILE_KEY = 'revealline.library.dev.v1',
+  SESSION_KEY = 'revealline.suspended.dev.v1',
+  source = JSON.parse(await readFile(new URL('../content/packs/fieldcraft.json', import.meta.url)));
+async function fixture(id, { version = '1.0.0', revision = '1' } = {}) {
+  const pack = structuredClone(source);
+  Object.assign(pack, { id, version, name: id });
+  Object.assign(pack.campaigns[0], {
+    id: `${id}-campaign`,
+    title: `${id} campaign`,
+    revision,
+  });
+  pack.campaigns[0].levels = [pack.campaigns[0].levels[0]];
+  Object.assign(pack.campaigns[0].levels[0], {
+    id: `${id}-level`,
+    name: `${id} revision ${revision}`,
+    revision,
+    goal: { coverage: revision === '1' ? 0.72 : 0.66 },
+  });
+  pack.levelVisuals = [];
+  return (await preparePack(pack)).pack;
+}
+const activePack = await fixture('active-flight'),
+  otherPack = await fixture('other-flight'),
+  addedPack = await fixture('new-flight'),
+  newerPack = await fixture('active-flight', { version: '2.0.0', revision: '2' }),
+  changedSameVersion = await fixture('active-flight', { revision: '3' });
+const libraryOf = (...packs) => packs.reduce(installPack, emptyPackLibrary());
+const installedBytes = (memory) => memory.contents().get('assets').get(PACKS_KEY);
+const row = (h, id) =>
+  [...h.$('installed-packs').children].find((item) => item.dataset.packId === id);
+const control = (h, id, kind) =>
+  row(h, id)?.children.find((item) => item.dataset.packAction === kind);
+const packTab = (h) => h.doc.querySelector('[data-library-panel="packs"]');
+
+// Use the actual handler through the ordinary button activation boundary.
+function action(element) {
+  const handler = element.onclick;
+  let result;
+  element.onclick = function (...args) {
+    return (result = handler.apply(this, args));
+  };
+  try {
+    element.click();
+  } finally {
+    element.onclick = handler;
+  }
+  return Promise.resolve(result);
+}
+async function seed(memory) {
+  const db = await new Promise((resolve, reject) => {
+    const request = memory.indexedDB.open('revealline-assets-v1', 1);
+    request.onupgradeneeded = () => request.result.createObjectStore('assets');
+    request.onsuccess = () => resolve(request.result);
+    request.onerror = () => reject(request.error);
+  });
+  await new Promise((resolve, reject) => {
+    const tx = db.transaction('assets', 'readwrite');
+    tx.objectStore('assets').put(exportPackLibrary(libraryOf(activePack, otherPack)), PACKS_KEY);
+    tx.oncomplete = resolve;
+    tx.onabort = () => reject(tx.error);
+  });
+  db.close();
+}
+async function pausedInstalledFlight(t) {
+  const show = SoloElement.prototype.showModal;
+  t.mock.method(SoloElement.prototype, 'showModal', function () {
+    if (this.open) return;
+    this.emit('beforetoggle', { oldState: 'closed', newState: 'open', bubbles: false });
+    show.call(this);
+  });
+  const memory = memoryIndexedDB();
+  await seed(memory);
+  let refuseNextPackWrite = false;
+  const h = await soloPage(t, {
+    titleScreen: true,
+    storage: memoryStorage({ [PROFILE_KEY]: exportLibrary(emptyLibrary()) }),
+    assetIndexedDB: memory.indexedDB,
+    lockManager: {
+      request(name, options, callback) {
+        if (refuseNextPackWrite && name.endsWith('.backup-lock')) {
+          refuseNextPackWrite = false;
+          return Promise.reject(new Error('Pack write deliberately refused'));
+        }
+        return Promise.resolve((callback ?? options)({ name }));
+      },
+    },
+  });
+  Object.assign(h.win, h.doc.defaultView);
+  h.doc.defaultView = h.win;
+  const baseLevelId = h.rendered.run.levelId;
+  h.$('shell-workshop').click();
+  h.$('shell-library').click();
+  packTab(h).click();
+  await action(control(h, activePack.id, 'play'));
+  await settle(() => {
+    h.frame(0);
+    return h.rendered.run.levelId === 'active-flight-level' && !h.$('library-dialog').open;
+  });
+  h.$('start-button').click();
+  await settle(() => {
+    h.frame(0);
+    return h.doc.body.dataset.flightState === 'running';
+  });
+  h.key('ArrowDown');
+  for (let i = 0; i < 30; i++) h.frame();
+  h.key('ArrowDown', false);
+  assert.equal(h.rendered.run.player.cutting, true, 'The fixture has a real unfinished cut.');
+  h.$('library-button').click();
+  packTab(h).click();
+  h.frame(0);
+  assert.equal(h.rendered.paused, true);
+  assert.equal(h.$('library-dialog').open, true);
+  const run = h.rendered.run,
+    checkpoint = authoritativeCheckpoint(run),
+    profile = h.storage.getItem(PROFILE_KEY),
+    session = h.storage.getItem(SESSION_KEY);
+  assert.ok(profile);
+  assert.ok(session, 'Opening Library records the paused installed attempt.');
+  return {
+    h,
+    memory,
+    run,
+    baseLevelId,
+    refuseWrite() {
+      refuseNextPackWrite = true;
+    },
+    assertUnchanged() {
+      h.frame(0);
+      assert.equal(h.rendered.run === run, true);
+      assert.deepEqual(authoritativeCheckpoint(h.rendered.run), checkpoint);
+      assert.equal(h.rendered.paused, true);
+      assert.equal(h.storage.getItem(PROFILE_KEY), profile);
+      assert.equal(h.storage.getItem(SESSION_KEY), session);
+      assert.deepEqual(h.errors, []);
+    },
+  };
+}
+async function importFile(h, value) {
+  h.$('pack-file').files = [
+    new File([typeof value === 'string' ? value : JSON.stringify(value)], 'packs.json', {
+      type: 'application/json',
+    }),
+  ];
+  await h.$('pack-file').onchange();
+  h.frame(0);
+  assert.match(h.$('pack-status').textContent, /Validated and installed/);
+  assert.equal(h.$('pack-file').value, '', 'The actual file input can be used again.');
+}
+
+test('actual Solo: removing the active installed pack selects the base campaign', async (t) => {
+  const { h, memory, run, baseLevelId } = await pausedInstalledFlight(t);
+  await action(control(h, activePack.id, 'remove'));
+  await settle(() => {
+    h.frame(0);
+    return h.rendered.run.levelId === baseLevelId;
+  });
+  assert.match(h.$('pack-status').textContent, /Pack removed/);
+  assert.equal(row(h, activePack.id), undefined);
+  assert.deepEqual(JSON.parse(installedBytes(memory)).packs, [otherPack]);
+  assert.equal(h.rendered.run === run, false, 'A removed active pack cannot keep executing.');
+  assert.equal(h.rendered.paused, true);
+  assert.equal(h.rendered.run.player.cutting, false);
+  assert.deepEqual(h.errors, []);
+});
+
+for (const [label, replacement] of [
+  ['newer version', newerPack],
+  ['same ID and version with changed content', changedSameVersion],
+]) {
+  test(`actual Solo: importing a library with active pack ${label} prepares its new level`, async (t) => {
+    const { h, memory, run } = await pausedInstalledFlight(t);
+    await importFile(h, exportPackLibrary(libraryOf(replacement, otherPack)));
+    await settle(() => {
+      h.frame(0);
+      return h.rendered.run.level.revision === replacement.campaigns[0].levels[0].revision;
+    });
+    assert.equal(h.rendered.run === run, false, 'Changed active content must replace the old run.');
+    assert.equal(
+      h.rendered.run.levelId,
+      run.levelId,
+      'Identity alone does not imply the same content.',
+    );
+    assert.equal(h.rendered.run.level.name, replacement.campaigns[0].levels[0].name);
+    assert.equal(h.rendered.run.level.goal.coverage, 0.66);
+    assert.equal(h.rendered.run.tick, 0);
+    assert.equal(h.rendered.run.player.cutting, false);
+    assert.equal(h.rendered.paused, true);
+    assert.deepEqual(JSON.parse(installedBytes(memory)).packs, [replacement, otherPack]);
+    assert.equal(row(h, activePack.id).dataset.packVersion, replacement.version);
+    assert.deepEqual(h.errors, []);
+  });
+}
+
+test('actual Solo: importing an unrelated pack preserves the exact paused installed flight', async (t) => {
+  const fixture = await pausedInstalledFlight(t),
+    { h, memory } = fixture;
+  await importFile(h, addedPack);
+  assert.deepEqual(JSON.parse(installedBytes(memory)).packs, [activePack, otherPack, addedPack]);
+  assert.ok(row(h, addedPack.id));
+  fixture.assertUnchanged();
+});
+
+test('actual Solo: rejected unrelated pack removal preserves the paused flight and stored packs', async (t) => {
+  const fixture = await pausedInstalledFlight(t),
+    { h, memory } = fixture,
+    before = installedBytes(memory);
+  fixture.refuseWrite();
+  await action(control(h, otherPack.id, 'remove'));
+  assert.match(
+    h.$('pack-status').textContent,
+    /Pack storage failed.*Pack write deliberately refused/,
+  );
+  assert.equal(installedBytes(memory), before);
+  assert.ok(row(h, otherPack.id));
+  fixture.assertUnchanged();
+});
